// ===== CONFIGURACIÓN =====
// Números que NUNCA reciben respuesta automática (solo dígitos, con código de país, sin +).
const EXCLUIDOS = [
  // '5491112345678',
];
const MAX_RESPUESTAS_POR_HORA = 10; // por chat, evita bucles con otros bots
const MAX_ANTIGUEDAD_SEG = 120;     // ignora mensajes viejos (al reconectar WAHA)
// =========================

const estado = $getWorkflowStaticData('global');
if (estado.ausente === undefined) estado.ausente = false;
if (!estado.nota) estado.nota = '';
if (!estado.contador) estado.contador = {};

const evento = $input.first().json.body || {};
const msg = evento.payload || {};
const texto = (msg.body || '').trim();
const chatId = msg.fromMe ? msg.to : msg.from;

if (!['message', 'message.any'].includes(evento.event) || !chatId) return [];

// Comandos: los escribís vos (fromMe) en el chat "Mensaje a mí mismo"
if (msg.fromMe) {
  const m = texto.match(/^\/ausente\s+(on|off|estado)\b\s*(.*)$/is);
  if (!m) return []; // tus mensajes normales (y las respuestas del bot) se ignoran
  const accion = m[1].toLowerCase();
  if (accion === 'on') {
    estado.ausente = true;
    estado.nota = m[2].trim();
  } else if (accion === 'off') {
    estado.ausente = false;
    estado.nota = '';
  }
  const resumen = estado.ausente
    ? `🤖 Modo ausente ACTIVADO${estado.nota ? ` (nota: "${estado.nota}")` : ''}.`
    : '🤖 Modo ausente DESACTIVADO.';
  return [{ json: { tipo: 'comando', session: evento.session, chatId, respuesta: resumen } }];
}

// Solo chats privados (descarta grupos, estados, canales, broadcast)
if (!/@(c\.us|s\.whatsapp\.net|lid)$/.test(chatId)) return [];
if (!estado.ausente) return [];
if (!texto || msg.hasMedia) return [];
if (msg.timestamp && Date.now() / 1000 - msg.timestamp > MAX_ANTIGUEDAD_SEG) return [];

const numero = chatId.split('@')[0];
if (EXCLUIDOS.includes(numero)) return [];

// Límite de respuestas por chat y por hora
const hora = Math.floor(Date.now() / 3600000);
const c = estado.contador[chatId];
const usados = c && c.hora === hora ? c.n : 0;
if (usados >= MAX_RESPUESTAS_POR_HORA) return [];
estado.contador[chatId] = { hora, n: usados + 1 };
for (const k of Object.keys(estado.contador)) {
  if (estado.contador[k].hora !== hora) delete estado.contador[k];
}

return [{
  json: {
    tipo: 'mensaje',
    session: evento.session,
    chatId,
    nombre: (msg._data && msg._data.notifyName) || '',
    texto,
    nota: estado.nota,
  },
}];
